    ref_tracks = get_tracks_from_file_id(ref_video_id)
    ref_activities = get_unique_activities_from_tracks(ref_tracks)
    ref_activity_species_map = {}
    for activity in ref_activities:
        tracks_with_activity = get_tracks_from_activity(ref_tracks, activity)
        species_set = set()
        for track in tracks_with_activity:
            for species in Species:
                tracks_of_species = get_tracks_from_species(ref_tracks, species)
                if track in tracks_of_species:
                    species_set.add(species)
                    break
        ref_activity_species_map[activity] = species_set
    target_tracks = get_tracks_from_file_id(file_id)
    for target_track in target_tracks:
        target_species = None
        for species in Species:
            tracks_of_species = get_tracks_from_species(target_tracks, species)
            if target_track in tracks_of_species:
                target_species = species
                break
        if target_species is None:
            continue
        target_activities = get_unique_activities_from_tracks([target_track])
        for activity in target_activities:
            if activity in ref_activity_species_map:
                for ref_species in ref_activity_species_map[activity]:
                    if ref_species != target_species:
                        return True
    return False

